<?php
declare(strict_types=1);
class UsuarioController extends Controller { public function index(): void { require_role('ADMINISTRADOR'); $m=new Usuario(); $this->view('usuarios/index',['roles'=>$m->roles(),'usuarios'=>$m->list()]); } public function store(): void { require_role('ADMINISTRADOR'); verify_csrf(); $nombre=post_text('nombre',120); $correo=strtolower(post_text('correo',150)); if(!filter_var($correo,FILTER_VALIDATE_EMAIL)) throw new RuntimeException('Correo inválido.'); $clave=(string)($_POST['clave']??''); if(strlen($clave)<8) throw new RuntimeException('La contraseña debe tener al menos 8 caracteres.'); $id=(new Usuario())->create($nombre,$correo,password_hash($clave,PASSWORD_DEFAULT),post_int('rol_id',1,99),post_enum('estado',['ACTIVO','INACTIVO'])); audit_log('CREAR_USUARIO','usuarios',$id,$correo); flash('success','Usuario registrado correctamente.'); redirect(url('usuario')); } }
